package rag;
import rag.runtime.*;
import dao.*;
import dto.*;
import dto.AdminKnowledgeDTO.*;
import ai.ConsultationBehaviorTest;
import ai.dto.*;
import ai.session.ChatSessionData;
import ai.exception.AIException;
import com.google.gson.*;
import java.sql.*;
import java.util.*;
import java.time.Instant;
import java.util.concurrent.*;
import static rag.RagPhase4RuntimeTest.*;

/** Real isolated PostgreSQL, synthetic keys and fake HTTP responses. Never live Gemini. */
public final class RagPhase4PostgresTest {
    static final RagDatabase DB=new RagDatabase();static int passed;
    static AdminKnowledgeDAO store;
    static final String TEXT="Anh/chị kiểm tra nguồn điện modem và vị trí đặt thiết bị WiFi an toàn.";
    static void run(String name,Case c)throws Exception{c.run();passed++;System.out.println("PASS Phase4-PostgreSQL "+name);}
    static long count(String sql)throws Exception{try(Connection c=DB.open();Statement s=c.createStatement();ResultSet r=s.executeQuery(sql)){r.next();return r.getLong(1);}}
    static void update(String sql)throws Exception{try(Connection c=DB.open();Statement s=c.createStatement()){s.execute(sql);}}
    static GeminiRuntimeConfig config(JsonObject p){return new GeminiRuntimeConfig(environment(),p);}
    static PostgresRequestLedger ledger(JsonObject p){return new PostgresRequestLedger(DB,config(p));}
    static ManagedDocument doc(String name,boolean publish)throws Exception{
        ManagedDocument d=store.createDocument("Hướng dẫn WiFi "+name,"guide",TEXT,"TEST_ONLY: focused runtime integration fixture","MANUAL","wifi","technical","test.wifi."+name,"official",null,null,null,800,80,"Offline test",1,"test-admin");
        if(publish){store.submitForReview(d.id,1,"test-admin","Test submit");store.approveDocument(d.id,2,"test-reviewer","Test approval");return store.publishDocument(d.id,2,"test-reviewer","Test publish");}return d;
    }
    static JsonObject documentPlan(ManagedDocument d)throws Exception{JsonObject p=plan();JsonObject v=new JsonObject();v.addProperty("id",d.id);v.addProperty("version",d.version);v.addProperty("hash",d.contentHash);p.getAsJsonArray("documents").add(v);for(String chunk:new DocumentChunkingService().chunk(d.content))allow(p,d.title,chunk,"DOCUMENT");return p;}
    static GeminiRuntime runtime(JsonObject p,GeminiEmbeddingService.Transport wire,ai.LLMProvider chat)throws Exception{
        GeminiRuntimeConfig cfg=config(p);PostgresRequestLedger l=new PostgresRequestLedger(DB,cfg);return new GeminiRuntime(cfg,DB,l,new RuntimeEmbeddingService(cfg,l,wire),chat);
    }
    public static void main(String[] args)throws Exception{
        if(!"true".equals(System.getenv("RAG_TEST_DATABASE_APPROVED"))||!"127.0.0.1".equals(System.getenv("DB_HOST"))||!"fpt_rag_test".equals(System.getenv("DB_NAME"))||!"false".equals(System.getenv("RAG_ENABLED")))throw new IllegalStateException("Isolated development DB required");
        GeminiRuntime.verifyDatabase(DB);update("CREATE TABLE public.settings (id SERIAL PRIMARY KEY,setting_key VARCHAR(120) UNIQUE NOT NULL,setting_value TEXT,description TEXT,updated_at TIMESTAMPTZ DEFAULT NOW())");store=new AdminKnowledgeDAO(DB);
        run("migration006 / journal RLS",()->{check(count("SELECT count(*) FROM pg_class WHERE relname IN ('rag_runtime_plans','rag_api_requests') AND relrowsecurity") ==2,"RLS enabled");});
        run("durable reservation visible before wire",()->{JsonObject p=plan();PostgresRequestLedger l=ledger(p);UUID id=l.reserve("QUERY","first","gemini-embedding-001",100);check(count("SELECT count(*) FROM rag_api_requests WHERE id='"+id+"' AND state='RESERVED'")==1,"committed reservation");l.finish(id,"COMPLETED",200,null,1,10,null,10);});
        run("unknown previous request blocks same/new plan on project",()->{JsonObject p=plan();ledger(p).reserve("QUERY","unknown","gemini-embedding-001",10);rejected(()->ledger(p).reserve("QUERY","next","gemini-embedding-001",10));JsonObject next=p.deepCopy();next.addProperty("planId","phase4-offline-"+UUID.randomUUID());rejected(()->ledger(next).reserve("QUERY","next","gemini-embedding-001",10));});
        run("UNCERTAIN blocks future request",()->{JsonObject p=plan();PostgresRequestLedger l=ledger(p);UUID id=l.reserve("QUERY","timeout","gemini-embedding-001",10);l.finish(id,"UNCERTAIN",0,"NETWORK_OR_TIMEOUT",1,null,null,null);rejected(()->l.reserve("QUERY","after-timeout","gemini-embedding-001",10));});
        run("duplicate operation cannot be sent twice",()->{JsonObject p=plan();PostgresRequestLedger l=ledger(p);UUID id=l.reserve("DOCUMENT","same-document","gemini-embedding-001",10);l.finish(id,"COMPLETED",200,null,1,null,null,null);rejected(()->l.reserve("DOCUMENT","same-document","gemini-embedding-001",10));check(count("SELECT count(*) FROM rag_api_requests WHERE plan_id='"+p.get("planId").getAsString()+"'")==1,"one durable entry");});
        run("plan mutation rejected",()->{JsonObject p=plan();PostgresRequestLedger l=ledger(p);UUID id=l.reserve("QUERY","old","gemini-embedding-001",10);l.finish(id,"COMPLETED",200,null,1,null,null,null);p.addProperty("maxChatOutputTokens",800);rejected(()->ledger(p).reserve("QUERY","new","gemini-embedding-001",10));});
        run("group and total budget across JVM-equivalent connections",()->{JsonObject p=plan();PostgresRequestLedger l=ledger(p);for(int i=0;i<2;i++){UUID id=l.reserve("QUERY","q"+i,"gemini-embedding-001",10);l.finish(id,"COMPLETED",200,null,1,null,null,null);}rejected(()->ledger(p).reserve("QUERY","q3","gemini-embedding-001",10));UUID d=l.reserve("DOCUMENT","d","gemini-embedding-001",10);l.finish(d,"COMPLETED",200,null,1,null,null,null);UUID chat=l.reserve("CHAT","c","gemini-3.8-flash",10);l.finish(chat,"COMPLETED",200,null,1,null,null,null);rejected(()->ledger(p).reserve("CHAT","c2","gemini-3.8-flash",10));check(count("SELECT count(*) FROM rag_api_requests WHERE plan_id='"+p.get("planId").getAsString()+"'")==4,"max four");});
        for(String limit:Arrays.asList("requestsPerMinute","requestsPerDay","tokensPerMinute","tokensPerDay"))run("failed slot counts toward "+limit,()->{JsonObject p=plan();if(limit.equals("requestsPerMinute"))p.addProperty(limit,1);else if(limit.equals("requestsPerDay")){p.addProperty("maxRequests",1);p.addProperty("documentRequests",0);p.addProperty("queryRequests",1);p.addProperty("chatRequests",0);p.addProperty(limit,1);}else p.addProperty(limit,10);PostgresRequestLedger l=ledger(p);UUID id=l.reserve("QUERY","failed","gemini-embedding-001",10);l.finish(id,"FAILED",429,"RATE_LIMIT",1,null,null,null);JsonObject next=p.deepCopy();next.addProperty("planId","phase4-offline-"+UUID.randomUUID());rejected(()->ledger(next).reserve("QUERY","next","gemini-embedding-001",10));});
        run("concurrent reservations exactly one in-flight",()->{JsonObject p=plan();ExecutorService pool=Executors.newFixedThreadPool(2);CountDownLatch gate=new CountDownLatch(1);List<Future<Boolean>> fs=new ArrayList<>();try{for(int i=0;i<2;i++){final int n=i;fs.add(pool.submit(()->{gate.await();try{ledger(p).reserve("QUERY","parallel"+n,"gemini-embedding-001",10);return true;}catch(RagException e){return false;}}));}gate.countDown();int accepted=0;for(Future<Boolean> f:fs)if(f.get(10,TimeUnit.SECONDS))accepted++;check(accepted==1,"concurrent requests exceeded lock");}finally{pool.shutdownNow();}});
        run("journal refuses sensitive arbitrary error text",()->{JsonObject p=plan();PostgresRequestLedger l=ledger(p);UUID id=l.reserve("QUERY","diagnostic","gemini-embedding-001",10);rejected(()->l.finish(id,"FAILED",401,"secret-url?key=synthetic",1,null,null,null));check(count("SELECT count(*) FROM rag_api_requests WHERE id='"+id+"' AND error_code IS NULL")==1,"sensitive text not persisted");});
        run("actual JDBC database target guard",()->{RagDatabase wrong=new RagDatabase(()->DriverManager.getConnection("jdbc:postgresql://127.0.0.1:"+System.getenv("DB_PORT")+"/postgres",System.getenv("DB_USER"),System.getenv("DB_PASSWORD")));rejected(()->GeminiRuntime.verifyDatabase(wrong));});
        run("DRAFT not indexable even allowlisted; no API",()->{ManagedDocument d=doc("draft",false);JsonObject p=documentPlan(d);GeminiRuntime rt=runtime(p,(a,b,c,e,f)->{throw new AssertionError("Draft sent to wire");},null);rejected(()->store.requestGeminiIndex(d.id,1,"test-admin",rt));check(store.findDocument(d.id).indexedVersion==null,"draft not indexed");});
        final ManagedDocument[] indexed={null};final GeminiRuntime[] rt={null};final int[] calls={0};final ConsultationBehaviorTest.MockProvider chat=new ConsultationBehaviorTest.MockProvider(){
            public synchronized ChatResponse chat(List<ChatMessage> messages,String key,String model,String base,ChatOptions options)throws AIException{
                this.calls++;lastModel=model;lastOptions=options;check(key.equals("synthetic-chat-key"),"production key leaked");String data=messages.get(messages.size()-1).getContent();JsonObject context=JsonParser.parseString(data.substring(data.indexOf('{'),data.lastIndexOf('}')+1)).getAsJsonObject();JsonObject reply=JsonParser.parseString(ConsultationBehaviorTest.envelope("Dạ anh/chị tham khảo hướng dẫn nhé.").getContent()).getAsJsonObject();JsonArray ids=new JsonArray();for(JsonElement e:context.getAsJsonArray("knowledgeContext"))ids.add(e.getAsJsonObject().get("id"));reply.add("knowledgeChunkIds",ids);return ConsultationBehaviorTest.raw(reply.toString(),"STOP");}
        };
        run("MOCK chunks excluded from GEMINI retrieval before real index",()->{ManagedDocument d=doc("runtime",true);store.reindexDocumentOffline(d.id,1,"test-admin");check(count("SELECT count(*) FROM knowledge_chunks WHERE document_id="+d.id+" AND embedding_provider='MOCK'")>0,"mock fixture exists");JsonObject p=documentPlan(d);allow(p,null,"Kiểm tra nguồn điện modem WiFi thế nào?","QUERY");p.getAsJsonArray("questions").add("Kiểm tra nguồn điện modem WiFi thế nào?");rt[0]=runtime(p,(method,url,key,body,deadline)->{calls[0]++;return new GeminiEmbeddingService.Result(200,vector(768));},chat);check(rt[0].retrieval.lookup("Kiểm tra nguồn điện modem WiFi thế nào?").chunks.isEmpty(),"mock chunks entered real space");indexed[0]=d;});
        run("approved published real adapter index stores 768 normalized GEMINI vector",()->{ManagedDocument d=store.requestGeminiIndex(indexed[0].id,1,"test-admin",rt[0]);check(d.embeddingProvider.equals("GEMINI")&&d.getRuntimeIndexStatus().equals("INDEXED")&&d.lastIndexedAt!=null&&d.indexedVersion.longValue()==d.version,"real index diagnostics");check(count("SELECT count(*) FROM knowledge_chunks WHERE document_id="+d.id+" AND embedding_provider='GEMINI' AND vector_dims(embedding)=768")==1,"real namespace vector");indexed[0]=d;});
        run("real query retrieval -> Chat -> validated extractive customer message",()->{ChatResponse answer=rt[0].chat("Kiểm tra nguồn điện modem WiFi thế nào?",new ChatSessionData("phase4-offline"),ConsultationBehaviorTest.CATALOG,ai.consultation.ConsultationPrompt.SYSTEM);check(answer.getContent().contains(TEXT)&&!answer.getContent().contains("knowledgeChunkIds")&&!answer.getContent().contains("embedding_provider")&&chat.calls==1,"grounded customer text; offline answer="+answer.getContent()+" chatCalls="+chat.calls+" embeddingCalls="+calls[0]);check(calls[0]==3&&chat.lastModel.equals("gemini-3.8-flash")&&chat.lastOptions.getThinkingLevel().equals("medium"),"one doc + two query + one Chat");});
        run("quota exhausted indexing WAITING_FOR_QUOTA without auto retry",()->{ManagedDocument d=doc("quota",true);JsonObject p=documentPlan(d);int[] n={0};GeminiRuntime runtime=runtime(p,(a,b,c,e,f)->{n[0]++;return new GeminiEmbeddingService.Result(429,"");},null);ManagedDocument failed=store.requestGeminiIndex(d.id,1,"test-admin",runtime);check(failed.getRuntimeIndexStatus().equals("WAITING_FOR_QUOTA")&&failed.embeddingError.equals("RATE_LIMIT"),"quota state");check(!runtime.index(d.id)&&n[0]==1,"no automatic retry");});
        run("provider failure indexing FAILED_RETRYABLE no auto claim",()->{ManagedDocument d=doc("provider",true);JsonObject p=documentPlan(d);int[] n={0};GeminiRuntime runtime=runtime(p,(a,b,c,e,f)->{n[0]++;return new GeminiEmbeddingService.Result(500,"");},null);ManagedDocument failed=store.requestGeminiIndex(d.id,1,"test-admin",runtime);check(failed.indexingStatus.equals("failed_retryable")&&!runtime.index(d.id)&&n[0]==1,"retryable requires explicit new plan");});
        run("version changes during embedding cannot commit stale chunks",()->{ManagedDocument d=doc("stale",true);JsonObject p=documentPlan(d);GeminiRuntime runtime=runtime(p,(a,b,c,e,f)->{try{store.unpublishDocument(d.id,1,"test-admin","Offline race");}catch(Exception x){throw new java.io.IOException("Offline mutation failed");}return new GeminiEmbeddingService.Result(200,vector(768));},null);store.requestGeminiIndex(d.id,1,"test-admin",runtime);check(store.findDocument(d.id).indexedVersion==null&&count("SELECT count(*) FROM knowledge_chunks WHERE document_id="+d.id+" AND embedding_provider='GEMINI'")==0,"stale write prevented");});
        run("unpublished source immediately excluded",()->{store.unpublishDocument(indexed[0].id,1,"test-admin","Disable source offline");check(new KnowledgeChunkDAO(DB,"GEMINI").search("modem wifi",null,"gemini-embedding-001",768,12).isEmpty(),"unpublished source retrieval");});
        run("strict embedding failure returns safe fallback without Chat",()->{JsonObject p=plan();String q="Hướng dẫn kiểm tra nguồn điện modem WiFi?";allow(p,null,q,"QUERY");p.getAsJsonArray("questions").add(q);ConsultationBehaviorTest.MockProvider wire=new ConsultationBehaviorTest.MockProvider();GeminiRuntime runtime=runtime(p,(a,b,c,e,f)->new GeminiEmbeddingService.Result(429,""),wire);ChatResponse result=runtime.chat(q,new ChatSessionData("query-failed"),ConsultationBehaviorTest.CATALOG,ai.consultation.ConsultationPrompt.SYSTEM);check(wire.calls==0&&!result.getProvider().equals("gemini"),"strict error must not fall back to ungrounded Chat");});
        run("core source business assertions still rejected",()->{check(KnowledgeContentPolicy.contentReason("Hướng dẫn WiFi","Giá gói 195K là 100.000đ/tháng")!=KnowledgeContentPolicy.Reason.ACCEPTED,"price guard weakened");});
        System.out.println("Phase4 PostgreSQL: "+passed+" passed; real API requests=0");
    }
}
